values
  ('00000000-0000-4000-8000-000000090801', null, 'official', 'Supino reto com barra', 'Exercicio basico para forca e hipertrofia de peitoral com apoio em banco reto.', 'Peitoral', 'Musculacao', 'Deite no banco, mantenha escápulas firmes, desça a barra com controle ate a linha media do peito e empurre sem perder a estabilidade dos ombros.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
  ('00000000-0000-4000-8000-000000090802', null, 'official', 'Supino inclinado com halteres', 'Variacao de supino com halteres para enfase em peitoral superior.', 'Peitoral', 'Musculacao', 'Ajuste o banco inclinado, mantenha os punhos alinhados, desça os halteres de forma simetrica e suba aproximando as maos sem bater os pesos.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
  ('00000000-0000-4000-8000-000000090803', null, 'official', 'Crucifixo na maquina', 'Movimento guiado de aducao horizontal para peitoral.', 'Peitoral', 'Musculacao', 'Ajuste o assento para alinhar as maos ao peito, mantenha cotovelos levemente flexionados e aproxime os apoios controlando a volta.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
