  ('00000000-0000-4000-8000-000000090805', null, 'official', 'Remada curvada com barra', 'Remada livre para costas com demanda de estabilizacao de tronco.', 'Costas', 'Musculacao', 'Incline o tronco com coluna neutra, puxe a barra em direcao ao abdome, aproxime as escapulas e controle a descida.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
