  ('00000000-0000-4000-8000-000000090808', null, 'official', 'Elevacao lateral com halteres', 'Isolamento para deltoide lateral.', 'Ombros', 'Musculacao', 'Com cotovelos levemente flexionados, eleve os halteres ate a linha dos ombros e retorne devagar mantendo o tronco estavel.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
