  ('00000000-0000-4000-8000-000000090816', null, 'official', 'Cadeira extensora', 'Extensao guiada de joelhos para quadriceps.', 'Quadriceps', 'Musculacao', 'Ajuste o encosto e o rolo, estenda os joelhos ate a amplitude planejada e controle a descida sem tirar o quadril do assento.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
  ('00000000-0000-4000-8000-000000090817', null, 'official', 'Levantamento terra romeno', 'Hinge de quadril com enfase em posteriores de coxa.', 'Posteriores', 'Musculacao', 'Segure a barra, leve o quadril para tras com joelhos levemente flexionados, mantenha a coluna neutra e suba contraindo posteriores e gluteos.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
  ('00000000-0000-4000-8000-000000090818', null, 'official', 'Mesa flexora', 'Flexao de joelhos deitado para posteriores de coxa.', 'Posteriores', 'Musculacao', 'Ajuste o rolo perto dos tornozelos, flexione os joelhos sem tirar o quadril do apoio e retorne de forma controlada.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
