  ('00000000-0000-4000-8000-000000090824', null, 'official', 'Abdominal crunch no solo', 'Flexao curta de tronco para reto abdominal.', 'Core', 'Em casa', 'Deite com joelhos flexionados, suba o tronco ate retirar as escapulas do solo e retorne devagar sem puxar o pescoco.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
