  ('00000000-0000-4000-8000-000000090826', null, 'official', 'Flexao de bracos', 'Empurrada horizontal com peso corporal para peitoral, ombros e triceps.', 'Peitoral', 'Em casa', 'Apoie maos no solo, alinhe tronco e quadril, desca com cotovelos controlados e empurre mantendo o corpo firme.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
