  ('00000000-0000-4000-8000-000000090828', null, 'official', 'Burpee', 'Movimento global de condicionamento com agachamento, prancha e salto.', 'Corpo inteiro', 'Funcional', 'Desca ao solo com controle, estenda as pernas para a posicao de prancha, retorne os pes e finalize em pe conforme o nivel prescrito.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
  ('00000000-0000-4000-8000-000000090829', null, 'official', 'Caminhada na esteira', 'Exercicio aerobico de baixo impacto em esteira.', 'Corpo inteiro', 'Aerobico', 'Ajuste velocidade e inclinacao conforme prescricao, mantenha postura alta e caminhe sem apoiar peso excessivo nas barras laterais.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z'),
  ('00000000-0000-4000-8000-000000090830', null, 'official', 'Mobilidade de quadril em 90/90', 'Exercicio de mobilidade para rotacao interna e externa do quadril.', 'Gluteos', 'Mobilidade', 'Sente no solo com as pernas em 90/90, mantenha o tronco alto e alterne a inclinacao do tronco ou a troca de lados conforme orientacao.', '', null, null, null, null, 'active', '{"catalog":"aruka_official_v1","version":"09.8"}'::jsonb, null, '2026-09-07T15:00:00Z', '2026-09-07T15:00:00Z')
on conflict (id) do update
set owner_id = excluded.owner_id,
